tools.usage:
hostid
printf '%x\n' $(hostid)
echo Host ID: $(hostid)

csplit file.txt /pattern/ {*}
csplit log.txt '/ERROR/' '{10}'
csplit -f part_ data.txt 100 200 300

logname
echo 'User:' $(logname)
if [ $(logname) = 'admin' ]; then echo 'Admin user'; fi

arch
echo 'Architecture:' $(arch)
case $(arch) in x86_64) echo '64-bit system';; esac
